<template><div class="config-item" :class="{highlight:isHighlighted}"><div class="config-item-label">{{fieldLabel}}</div><div class="config-item-control"><div v-if="field.type==='color'" class="color-wrapper"><el-color-picker v-model="localValue" show-alpha :predefine="preColors" /><el-input v-model="localValue" size="mini" class="color-text-input" /></div><div v-else-if="field.type==='switch'"><el-switch v-model="localValue" :active-value="true" :inactive-value="false" /><span class="switch-status">{{localValue?'已开启':'已关闭'}}</span></div><el-input v-else-if="field.type==='text'" v-model="localValue" :placeholder="field.placeholder" :maxlength="field.maxlength" style="width:220px" /><el-input-number v-else-if="field.type==='number'" v-model="localValue" :min="field.min" :max="field.max" :step="field.step||1" size="small" controls-position="right" /><el-select v-else-if="field.type==='select'" v-model="localValue" :multiple="field.multiple" placeholder="" style="width:100%"><el-option v-for="opt in field.options" :key="opt.value" :label="opt.label" :value="opt.value" /></el-select><div v-else-if="field.type==='slider'" class="slider-wrapper"><el-slider v-model="localValue" :min="field.min" :max="field.max" :step="field.step" style="flex:1" /><span class="slider-value">{{localValue}}</span></div><el-select v-else-if="field.type==='icon'" v-model="localValue" filterable clearable style="width:260px"><el-option v-for="icon in iconOptions" :key="icon" :label="icon" :value="icon"><i :class="icon" style="margin-right:6px" />{{icon}}</el-option></el-select><div v-else-if="field.type==='image'" class="image-wrapper"><el-upload :action="uploadUrl" :headers="uploadHeaders" :show-file-list="false" :on-success="handleUploadSuccess" :on-error="()=>$message.error('上传失败')"><img v-if="localValue" :src="localValue" class="image-preview" /><el-button v-else size="small" type="primary">选择图片</el-button></el-upload><el-button v-if="localValue" size="mini" type="danger" circle icon="el-icon-delete" @click="localValue=''" /></div><div v-else-if="field.type==='kvlist'" class="kvlist-wrapper"><div v-for="(item,idx) in (localValue||[])" :key="idx" class="kv-row"><el-input v-model="item.label" placeholder="" size="mini" style="width:120px;margin-right:4px" /><el-input v-model="item.value" placeholder="" size="mini" style="width:200px;margin-right:4px" /><el-button type="danger" icon="el-icon-delete" size="mini" circle @click="removeKv(idx)" /></div><el-button size="mini" type="primary" @click="addKv">+ 添加</el-button></div><el-select v-else-if="field.type==='tags'" v-model="localValue" multiple filterable allow-create default-first-option style="width:100%"><el-option v-for="opt in field.options" :key="opt.value" :label="opt.label" :value="opt.value" /></el-select><div v-if="field.desc" class="field-desc">{{field.desc}}</div></div></div></template>
<script>export default{name:'ConfigItem',props:{field:{type:Object,required:true},value:{default:undefined},preColors:{type:Array,default:()=>[]},iconOptions:{type:Array,default:()=>[]},uploadUrl:{type:String,default:''},uploadHeaders:{type:Object,default:()=>({})},searchQuery:{type:String,default:''}},emits:['update'],computed:{localValue:{get(){return this.value},set(v){this.$emit('update',v)}},fieldLabel(){return this.field.label||this.field.key},isHighlighted(){if(!this.searchQuery)return false;const q=this.searchQuery.toLowerCase();return(this.field.label||'').toLowerCase().includes(q)||(this.field.key||'').toLowerCase().includes(q)||(this.field.desc||'').toLowerCase().includes(q)}},methods:{handleUploadSuccess(res){if(res.code===0){this.localValue=res.data.url;this.$message.success('OK')}else{this.$message.error(res.message||'FAIL')}},addKv(){const arr=[...(Array.isArray(this.localValue)?this.localValue:[])];arr.push({label:'',value:''});this.localValue=arr},removeKv(idx){const arr=[...(this.localValue||[])];arr.splice(idx,1);this.localValue=arr}}}</script>
<style scoped>.config-item{display:flex;align-items:flex-start;padding:8px 0;border-bottom:1px solid #f8fafc;transition:background-color .5s;border-radius:4px}.config-item:last-child{border-bottom:none}.config-item.highlight{background-color:#fef9c3;animation:flash-highlight 1.5s ease}@keyframes flash-highlight{0%{background-color:#fef9c3}50%{background-color:#fef08a}100%{background-color:#fef9c3}}.config-item-label{width:140px;min-width:140px;font-size:13.5px;color:#475569;line-height:32px;flex-shrink:0}.config-item-control{flex:1;min-width:0}.color-wrapper{display:flex;align-items:center;gap:8px}.color-text-input{width:120px!important}.switch-status{font-size:12px;color:#94a3b8;margin-left:8px}.slider-wrapper{display:flex;align-items:center;gap:12px}.slider-value{font-size:13px;color:#475569;min-width:32px}.image-wrapper{display:flex;align-items:center;gap:8px}.image-preview{width:80px;height:80px;object-fit:cover;border-radius:6px;border:1px solid #dcdfe6;cursor:pointer}.kvlist-wrapper{width:100%}.kv-row{display:flex;align-items:center;margin-bottom:4px}.field-desc{font-size:12px;color:#94a3b8;margin-top:2px}</style>
